// Global variables
let stocksData = [];
let selectedTicker = null;

// Color scale for sectors
const sectorColors = {
    'Information Technology': '#1f77b4',
    'Industry': '#ff7f0e',
    'Energy': '#2ca02c',
    'Financial': '#d62728',
    'ETF': '#9467bd'
};

// Format market cap for display
function formatMarketCap(value) {
    if (!value || isNaN(value)) return 'N/A';

    const trillion = 1e12;
    const billion = 1e9;
    const million = 1e6;

    if (value >= trillion) {
        return (value / trillion).toFixed(2) + 'T';
    } else if (value >= billion) {
        return (value / billion).toFixed(2) + 'B';
    } else if (value >= million) {
        return (value / million).toFixed(2) + 'M';
    } else {
        return value.toFixed(0);
    }
}

// Load and process data
d3.csv('data/stock-descriptions.csv').then(data => {
    stocksData = data.map(d => ({
        ticker: d.ticker,
        sector: d.sector,
        name: d['full name'],
        marketCap: +d.marketCap || null,
        country: d.country,
        website: d.website
    }));

    createBubbleChart();
    createTable();
});

// Create bubble chart
function createBubbleChart() {
    const width = 900;
    const height = 700;
    const margin = { top: 40, right: 20, bottom: 80, left: 20 };

    const svg = d3.select('#bubble-chart')
        .append('svg')
        .attr('width', width)
        .attr('height', height);

    // Create tooltip
    const tooltip = d3.select('body')
        .append('div')
        .attr('class', 'tooltip');

    // Calculate bubble sizes
    const marketCaps = stocksData.filter(d => d.marketCap).map(d => d.marketCap);
    const minMarketCap = d3.min(marketCaps);
    const maxMarketCap = d3.max(marketCaps);

    const radiusScale = d3.scaleSqrt()
        .domain([minMarketCap, maxMarketCap])
        .range([15, 50]);

    // ETF uniform size
    const etfRadius = 25;

    // Add radius to data
    stocksData.forEach(d => {
        d.radius = d.marketCap ? radiusScale(d.marketCap) : etfRadius;
    });

    // Group stocks by sector for positioning
    const sectors = [...new Set(stocksData.map(d => d.sector))];
    const sectorCenters = {};

    // Calculate sector centers - arrange in a grid pattern
    const numSectors = sectors.length;
    const cols = Math.ceil(Math.sqrt(numSectors));
    const rows = Math.ceil(numSectors / cols);
    const sectorSpacingX = (width - margin.left - margin.right) / cols;
    const sectorSpacingY = (height - margin.top - margin.bottom) / rows;

    sectors.forEach((sector, i) => {
        const col = i % cols;
        const row = Math.floor(i / cols);
        sectorCenters[sector] = {
            x: margin.left + sectorSpacingX * (col + 0.5),
            y: margin.top + sectorSpacingY * (row + 0.5)
        };
    });

    // Create simulation
    const simulation = d3.forceSimulation(stocksData)
        .force('x', d3.forceX(d => sectorCenters[d.sector].x).strength(0.1))
        .force('y', d3.forceY(d => sectorCenters[d.sector].y).strength(0.1))
        .force('collide', d3.forceCollide(d => d.radius + 2).strength(0.9))
        .force('charge', d3.forceManyBody().strength(-5));

    // Create bubbles
    const bubbles = svg.append('g')
        .selectAll('.bubble')
        .data(stocksData)
        .join('circle')
        .attr('class', 'bubble')
        .attr('r', d => d.radius)
        .attr('fill', d => sectorColors[d.sector] || '#999')
        .on('mouseover', function(event, d) {
            // Only show tooltip for non-ETF stocks
            if (d.sector !== 'ETF' && d.marketCap) {
                tooltip
                    .html(`
                        <strong>${d.ticker}</strong><br/>
                        ${d.name}<br/>
                        Sector: ${d.sector}<br/>
                        Market Cap: ${formatMarketCap(d.marketCap)}
                    `)
                    .style('left', (event.pageX + 10) + 'px')
                    .style('top', (event.pageY - 10) + 'px')
                    .classed('show', true);
            }
        })
        .on('mouseout', function() {
            tooltip.classed('show', false);
        })
        .on('click', function(event, d) {
            selectStock(d.ticker);
        });

    // Add labels
    const labels = svg.append('g')
        .selectAll('.bubble-label')
        .data(stocksData)
        .join('text')
        .attr('class', 'bubble-label')
        .text(d => d.ticker)
        .style('font-size', d => {
            // Scale font size based on bubble size
            return Math.max(8, Math.min(12, d.radius / 3)) + 'px';
        });

    // Update positions on simulation tick
    simulation.on('tick', () => {
        bubbles
            .attr('cx', d => d.x)
            .attr('cy', d => d.y);

        labels
            .attr('x', d => d.x)
            .attr('y', d => d.y + 4);
    });

    // Create legend
    const legend = d3.select('#bubble-chart')
        .append('div')
        .attr('class', 'legend');

    sectors.forEach(sector => {
        const item = legend.append('div')
            .attr('class', 'legend-item');

        item.append('div')
            .attr('class', 'legend-color')
            .style('background-color', sectorColors[sector] || '#999');

        item.append('span')
            .text(sector);
    });
}

// Create table
function createTable() {
    const tableContainer = d3.select('#stock-table');

    const table = tableContainer.append('table');
    const thead = table.append('thead');
    const tbody = table.append('tbody');

    // Add header
    thead.append('tr')
        .selectAll('th')
        .data(['Ticker', 'Company Name', 'Sector', 'Market Cap'])
        .join('th')
        .text(d => d);

    // Add rows
    const rows = tbody.selectAll('tr')
        .data(stocksData)
        .join('tr')
        .attr('data-ticker', d => d.ticker)
        .on('click', function(event, d) {
            selectStock(d.ticker);
        });

    rows.each(function(d) {
        const row = d3.select(this);

        row.append('td').text(d.ticker);
        row.append('td').text(d.name);
        row.append('td').text(d.sector);
        row.append('td').text(formatMarketCap(d.marketCap));
    });
}

// Select stock (sync between chart and table)
function selectStock(ticker) {
    selectedTicker = ticker;

    // Update bubble selection
    d3.selectAll('.bubble')
        .classed('selected', d => d.ticker === ticker);

    // Update table row selection
    d3.selectAll('tbody tr')
        .classed('selected', function() {
            return d3.select(this).attr('data-ticker') === ticker;
        });

    // Scroll selected row into view
    const selectedRow = document.querySelector(`tbody tr[data-ticker="${ticker}"]`);
    if (selectedRow) {
        selectedRow.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }
}

